#include "lossless_evidence.hpp"
#include <yaml-cpp/yaml.h>
#include <filesystem>
#include <iostream>
#include <fstream>
#include <sstream>
#include <iomanip>
#include <fcntl.h>
#include <unistd.h>
#include <cerrno>
namespace live=phase5_active_session_v1;namespace rt=phase5_active_session_runtime_v1;namespace ev=phase5_active_evidence_v1;
namespace {void need(bool x,const char* s){if(!x)throw std::runtime_error(s);}live::FileIdentity id(const YAML::Node& n){return {n["path"].as<std::string>(),n["sha256"].as<std::string>(),n["bytes"].as<live::Count>()};}void pin(const live::FileIdentity& f){const auto a=live::observePinnedFile(f.path,f.sha256);need(a.bytes==f.bytes,"warmup entry pin size");}}
class DurableWarmupJournal final {int fd=-1;std::size_t bytes=0,events=0;std::string path;public:explicit DurableWarmupJournal(const std::string& file):path(file){fd=::open(file.c_str(),O_WRONLY|O_CREAT|O_EXCL|O_NOFOLLOW|O_CLOEXEC,0600);need(fd>=0,"fresh durable warmup journal");}~DurableWarmupJournal(){if(fd>=0)::close(fd);}void append(const rt::WarmupPoint& p,const std::string& event){std::ostringstream o;o<<std::setprecision(17)<<event<<","<<p.substep<<","<<p.simulation_time<<","<<p.native_returned<<","<<p.native_joints_read<<","<<p.scratch_joints_read<<","<<p.contacts;for(int n:p.warnings)o<<","<<n;for(const auto* v:{&p.q,&p.v,&p.C,&p.acceleration,&p.jerk})for(double x:*v)o<<","<<x;o<<","<<p.jerk_available<<","<<p.geometry_complete<<","<<p.independent_observer_guard<<","<<p.minimum_true<<","<<p.minimum_cover<<","<<p.geometry_queries<<","<<p.tcp_frame_error<<","<<p.arm_frame_error<<"\n";const auto line=o.str();need(line.size()<=4096&&bytes+line.size()<=12582912,"bounded durable warmup journal");std::size_t n=0;while(n<line.size()){const auto k=::write(fd,line.data()+n,line.size()-n);if(k<0&&errno==EINTR)continue;need(k>0,"durable journal write prefix retained");n+=k;bytes+=k;}need(::fsync(fd)==0,"durable warmup journal fsync");++events;}void receipt(ev::Evidence& out){need(::fsync(fd)==0,"journal final fsync");std::ifstream in(path,std::ios::binary);need(bool(in),"journal receipt open");std::unique_ptr<EVP_MD_CTX,decltype(&EVP_MD_CTX_free)> h(EVP_MD_CTX_new(),EVP_MD_CTX_free);need(h&&EVP_DigestInit_ex(h.get(),EVP_sha256(),nullptr)==1,"journal receipt hash init");char buffer[4096];std::size_t seen=0,newlines=0;char last=0;while(in){in.read(buffer,sizeof(buffer));const auto n=in.gcount();if(n>0){seen+=n;need(seen<=12582912&&EVP_DigestUpdate(h.get(),buffer,n)==1,"journal receipt bounded hash");for(int j=0;j<n;++j)if(buffer[j]=='\n')++newlines;last=buffer[n-1];}}need(in.eof(),"journal receipt complete read");unsigned char digest[32];unsigned n=0;need(EVP_DigestFinal_ex(h.get(),digest,&n)==1&&n==32,"journal final hash");std::string sha;const char* hex="0123456789abcdef";for(unsigned char b:digest){sha.push_back(hex[b>>4]);sha.push_back(hex[b&15]);}const auto pin=live::observePinnedFile(path,sha);need(pin.bytes==seen,"journal receipt stable size/hash");out.write("journal_receipt.bin","ACTUAL_DURABLE_WARMUP_JOURNAL_PREFIX_V2",[&](ev::BinaryFile& f){f.text(path);f.text(sha);f.u64(seen);f.u64(bytes);f.u64(events);f.u64(newlines);f.u64(seen&&last!='\n');f.text("hard termination may leave final step-attempt without native-return: native entry/advancement UNKNOWN; retain exact complete newline prefix; binary128MiB plus separate journal12MiB caps");});}};
int main(int argc,char** argv){std::unique_ptr<ev::Evidence> out;std::unique_ptr<rt::Simulation> sim;std::unique_ptr<DurableWarmupJournal> journal;rt::Snapshot obs;std::string stage="BEFORE_INPUT",error;bool success=false,snapshot_attempted=false;std::vector<live::FileIdentity> pins;
 try{need(argc==5,"input/hash/producerhash/newoutput");live::observePinnedFile(argv[1],argv[2]);const auto input=YAML::LoadFile(argv[1]);need(input["schema"].as<std::string>()=="ACTIVE_TASK_PHYSICAL_WARMUP_DEV_V2","fresh warmup schema");out=std::make_unique<ev::Evidence>(argv[4]);auto producer=live::observeCurrentProducerElf(argv[3]);producer.path=std::filesystem::canonical("/proc/self/exe").string();pins.push_back(producer);
 for(const auto& n:input["dependencies"])pins.push_back(id(n));for(const auto& f:pins)pin(f);need(pins.size()<=128,"finite warmup pin roster");
 rt::WarmupSpec spec;spec.feasible_csv=id(input["feasible_csv"]);spec.robot_config=id(input["robot_config"]);spec.geometry_config=id(input["geometry_config"]);spec.task_reference=id(input["task_reference"]);spec.seed=input["seed"].as<unsigned>();spec.dependencies=pins;journal=std::make_unique<DurableWarmupJournal>(std::string(argv[4])+"/actual_step_journal.csv");spec.retain_event=[&](const auto& point,const auto& event){journal->append(point,event);};
 stage="OWNED_FULL_SCENE_BOOTSTRAP";sim=std::make_unique<rt::Simulation>(id(input["xml"]),input["epoch"].as<std::string>());stage="ACTUAL1000_TIMES2MS_WARMUP";const auto& w=sim->initializeAndWarmup(spec);out->warmup(w);need(w.success,w.error.c_str());stage="FRESH_CURRENT_AFTER_WARMUP";sim->observe(obs);snapshot_attempted=true;out->snapshot("actual_current.bin",obs);need(obs.completed()&&obs.actualObservation().boundary.completed_tick==0&&obs.acceptedHistory().boundary.completed_command_sequence==0&&obs.physicalHistory().total_actual_substeps==1000&&obs.physicalHistory().acceleration_available,"separate task0/actualphysical1000 boundary");success=true;stage="PASS_ACTUAL_TASK_WARMUP_COMPONENT_NO_MODEL_NO_CANDIDATE";
 }catch(const std::exception& e){error=e.what();}catch(...){error="unknown task warmup failure";}
 if(out&&!snapshot_attempted&&obs.stageName()!="NOT_STARTED")try{snapshot_attempted=true;out->snapshot("actual_current.bin",obs);}catch(const std::exception& e){if(error.empty())error=e.what();}
 bool terminal=false;try{if(sim)sim->verifyTermination();for(const auto& f:pins)pin(f);terminal=sim&&sim->terminationVerified();}catch(const std::exception& e){if(error.empty())error=e.what();}
 if(out&&journal)try{journal->receipt(*out);}catch(const std::exception& e){if(error.empty())error=e.what();}
 if(out&&sim)try{out->bootstrap(sim->facts());}catch(const std::exception& e){if(error.empty())error=e.what();}
 if(out)try{out->write("warmup_completion.bin","ACTIVE_SESSION_FINAL_SCOPE_AND_TIMING",[&](ev::BinaryFile& f){f.text(stage);f.text(error);f.u64(success);f.u64(terminal);f.u64(sim?sim->facts().warmup_step_attempts:0);f.u64(sim?sim->facts().warmup_completed_steps:0);f.u64(sim?sim->facts().commits:0);f.u64(0);f.u64(0);f.text("component bootstrap only; Model=0,nominal=0,QP=0,candidate=0,taskcommit=0; phase5 NOT_ACCEPTED");});}catch(const std::exception& e){if(error.empty())error=e.what();}
 if(out)try{out->finish(stage,error,false);}catch(const std::exception& e){if(error.empty())error=e.what();}
 std::cout<<"stage="<<stage<<" error="<<error<<" terminal="<<terminal<<" warmupsteps="<<(sim?sim->facts().warmup_completed_steps:0)<<" taskcommits=0 Model=0 phase5=NOT_ACCEPTED\n";return success&&terminal&&error.empty()?0:1;
}
